129	function syncWhoScene(progress: number): void {
130	  const textItems = Array.from(
131	    document.querySelectorAll<HTMLElement>(WHO_TEXT_SELECTOR),
132	  );
133	  if (textItems.length === 0) return;
134	
135	  const shouldShow = progress >= WHO_REVEAL_START && progress < WHO_REVEAL_END;
136	  if (mainSceneDomState.isWhoTextVisible === shouldShow) return;
137	  mainSceneDomState.isWhoTextVisible = shouldShow;
138	  mainSceneDomState.whoTextTimers = clearTimers(
139	    mainSceneDomState.whoTextTimers,
140	  );
141	
142	  const items = shouldShow ? textItems : textItems.slice().reverse();
143	  items.forEach((item, index) => {
144	    const timerId = window.setTimeout(
145	      () => {
146	        if (shouldShow) {
147	          TextReveal.setVisibleOn(item);
148	          return;
149	        }
150	        TextReveal.setVisibleOff(item);
151	      },
152	      index * WHO_REVEAL_STAGGER_SECONDS * 1000,
153	    );
154	    mainSceneDomState.whoTextTimers.push(timerId);
155	  });
156	}
157	
158	function disposeWhoScene(): void {
