171	function syncWorksDetailHead(progress: number): void {
172	  const head = document.querySelector<HTMLElement>(WORKS_DETAIL_HEAD_SELECTOR);
173	  if (!head) return;
174	  const textItems = Array.from(
175	    head.querySelectorAll<HTMLElement>(".mask-target"),
176	  );
177	  const shouldShow =
178	    progress >= WORKS_DETAIL_HEAD_TRANSITION.revealStart &&
179	    progress < WORKS_DETAIL_HEAD_TRANSITION.hideStart;
180	
181	  if (mainSceneDomState.isWorksDetailHeadVisible === shouldShow) return;
182	  mainSceneDomState.isWorksDetailHeadVisible = shouldShow;
183	  mainSceneDomState.worksDetailHeadTimers = clearTimers(
184	    mainSceneDomState.worksDetailHeadTimers,
185	  );
186	
187	  if (shouldShow) {
188	    head.dataset.active = "true";
189	    TextReveal.setVisibleOff(textItems);
190	    textItems.forEach((item, index) => {
191	      const timerId = window.setTimeout(
192	        () => {
193	          TextReveal.setVisibleOn(item);
194	        },
195	        index * WORKS_DETAIL_HEAD_TRANSITION.revealStagger * 1000,
196	      );
197	      mainSceneDomState.worksDetailHeadTimers.push(timerId);
198	    });
199	    return;
200	  }
201	
202	  textItems
203	    .slice()
204	    .reverse()
205	    .forEach((item, index) => {
206	      const timerId = window.setTimeout(
207	        () => {
208	          TextReveal.setVisibleOff(item);
209	        },
210	        index * WORKS_DETAIL_HEAD_TRANSITION.hideStagger * 1000,
211	      );
212	      mainSceneDomState.worksDetailHeadTimers.push(timerId);
213	    });
214	  const hideTimerId = window.setTimeout(
215	    () => {
216	      head.dataset.active = "false";
217	    },
218	    (Math.max(textItems.length - 1, 0) *
219	      WORKS_DETAIL_HEAD_TRANSITION.hideStagger +
220	      WORKS_DETAIL_HEAD_TRANSITION.hideSettleDuration) *
221	      1000,
222	  );
223	  mainSceneDomState.worksDetailHeadTimers.push(hideTimerId);
224	}
