248	  if (mainSceneDomState.isClientItemsVisible === shouldShow) return;
249	  mainSceneDomState.isClientItemsVisible = shouldShow;
250	  mainSceneDomState.clientItemTimers = clearTimers(
251	    mainSceneDomState.clientItemTimers,
252	  );
253	
254	  const queue = shouldShow ? items : items.slice().reverse();
255	  queue.forEach((item, index) => {
256	    const timerId = window.setTimeout(
257	      () => {
258	        item.classList.add(INIT_DOM_CLASSES.blockBase);
259	        item.classList.remove(INIT_DOM_CLASSES.boxHidden);
260	        item.classList.remove("is-block-reveal-down");
261	        if (shouldShow) {
262	          BlockReveal.reveal(item);
263	          return;
264	        }
265	        item.classList.remove(INIT_DOM_CLASSES.blockUp);
266	        item.classList.add("is-block-reveal-down");
267	      },
268	      index * CLIENT_REVEAL_STAGGER_SECONDS * 1000,
269	    );
