382	function disposeContactHead(): void {
383	  mainSceneDomState.isContactHeadVisible = false;
384	  mainSceneDomState.contactHeadTimers = clearTimers(
385	    mainSceneDomState.contactHeadTimers,
386	  );
387	  mainSceneDomState.isContactActionsVisible = false;
388	  mainSceneDomState.contactActionTimers = clearTimers(
389	    mainSceneDomState.contactActionTimers,
390	  );
391	  const section = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
392	  const head = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
393	  const actions = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
394	  if (!section || !head || !actions) return;
395	  section.dataset.active = "false";
396	  head.dataset.active = "false";
397	  actions.dataset.active = "false";
398	  const textItems = Array.from(
399	    head.querySelectorAll<HTMLElement>(".mask-target"),
400	  );
401	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
402	  const actionItems = Array.from(
403	    document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR),
404	  );
405	  actionItems.forEach((item) => {
406	    item.classList.add(INIT_DOM_CLASSES.blockBase);
407	    item.classList.remove(INIT_DOM_CLASSES.blockUp, "is-block-reveal-down");
408	    item.classList.add(INIT_DOM_CLASSES.boxHidden);
409	  });
410	}
