153	function syncAboutContactHead(progress: number): void {
154	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
155	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
156	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
157	  if (!section || !head || !actions) return;
158	
159	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
160	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
161	
162	  if (aboutSceneDomState.isContactHeadVisible === shouldShow) return;
163	  aboutSceneDomState.isContactHeadVisible = shouldShow;
164	  aboutSceneDomState.contactHeadTimers = clearTimers(
165	    aboutSceneDomState.contactHeadTimers,
166	  );
167	
168	  if (shouldShow) {
169	    section.dataset.active = "true";
170	    head.dataset.active = "true";
171	    actions.dataset.active = "true";
172	    TextReveal.setVisibleOff(textItems);
173	    textItems.forEach((item, index) => {
174	      const timerId = window.setTimeout(() => {
175	        TextReveal.setVisibleOn(item);
176	      }, index * CONTACT_HEAD_TRANSITION.revealStagger * 1000);
177	      aboutSceneDomState.contactHeadTimers.push(timerId);
178	    });
179	    return;
180	  }
181	
182	  textItems.forEach((item) => {
183	    TextReveal.setVisibleOff(item);
184	  });
185	  section.dataset.active = "false";
186	  head.dataset.active = "false";
187	  actions.dataset.active = "false";
188	}
