32	function disposeShaderUniformTextures(material: THREE.Material): void {
33	  const shader = material as THREE.ShaderMaterial;
34	  if (!shader.uniforms) return;
35	  for (const key of Object.keys(shader.uniforms)) {
36	    const value = shader.uniforms[key]?.value;
37	    if (value instanceof THREE.Texture) value.dispose();
38	  }
39	}
40	
41	export function disposeMaterial(material: THREE.Material): void {
42	  const mat = material as MaterialWithTextures;
43	  for (const slot of TEXTURE_SLOTS) {
44	    const tex = mat[slot];
45	    if (tex) tex.dispose();
46	  }
47	  disposeShaderUniformTextures(material);
48	  material.dispose();
49	}
50	
51	export function disposeObject3D(object3D: THREE.Object3D): void {
52	  object3D.traverse((child) => {
53	    const node = child as Object3DWithResources;
54	    node.geometry?.dispose();
55	    const material = node.material;
56	    if (Array.isArray(material)) {
57	      material.forEach(disposeMaterial);
58	    } else if (material) {
59	      disposeMaterial(material);
60	    }
61	  });
62	}
63	
64	export function removeAndDispose(
65	  node: THREE.Object3D | null,
66	  parent?: THREE.Object3D | null,
67	): null {
68	  if (!node) return null;
69	  const host = parent ?? node.parent;
70	  host?.remove(node);
71	  disposeObject3D(node);
72	  return null;
73	}
