342	  private _syncFlameBillboard(): void {
343	    const root = this.getTimelineRoot();
344	    const flameMesh = this._flameMesh;
345	    const camera = this._context?.camera;
346	    if (!root || !flameMesh || !camera) return;
347	
348	    camera.getWorldQuaternion(this._cameraWorldQuaternion);
349	    root.getWorldQuaternion(this._rootWorldQuaternion);
350	    this._rootWorldQuaternion.invert();
351	    flameMesh.quaternion
352	      .copy(this._rootWorldQuaternion)
