370	  private _resolveFlameAnchor(model: THREE.Group): THREE.Object3D | null {
371	    const flameOptions = this._resolveFlameOptions();
372	    const explicitAnchor = this._findExplicitFlameAnchor(model, flameOptions);
373	    if (explicitAnchor) return explicitAnchor;
374	    return this._findHeuristicFlameAnchor(model, flameOptions);
375	  }
376	
377	  private _findExplicitFlameAnchor(
378	    model: THREE.Group,
379	    options: RocketFlameOptions,
380	  ): THREE.Object3D | null {
381	    const anchorName = options.anchorName?.trim();
382	    if (!anchorName) return null;
383	    const target = model.getObjectByName(anchorName);
384	    if (!target) {
385	      Logger.warn(
386	        ROCKET_CLASS,
387	        "runObject",
388	        `Rocket flame anchor "${anchorName}" was not found. Falling back to heuristics.`,
389	      );
390	      return null;
391	    }
392	    return target;
393	  }
394	
395	  private _findHeuristicFlameAnchor(
396	    model: THREE.Group,
397	    options: RocketFlameOptions,
398	  ): THREE.Object3D | null {
399	    const normalizedIncludes = this._getNormalizedFlameAnchorIncludes(options);
400	    let bestMatch: THREE.Object3D | null = null;
401	
402	    model.traverse((child) => {
403	      if (bestMatch || child === model) return;
404	      const normalizedName = child.name.trim().toLowerCase();
405	      if (!normalizedName) return;
406	      if (!normalizedIncludes.some((value) => normalizedName.includes(value)))
407	        return;
408	      bestMatch = child;
409	    });
410	
411	    if (!bestMatch) {
412	      Logger.warn(
413	        ROCKET_CLASS,
414	        "runObject",
415	        "Rocket flame anchor was not found by name. Falling back to bounding-box placement.",
416	      );
417	    }
418	
419	    return bestMatch;
420	  }
421	
422	  private _logFlameAnchorDebug(
423	    model: THREE.Group,
424	    anchor: THREE.Object3D | null,
425	  ): void {
426	    if (this._hasLoggedFlameAnchorDebug) return;
427	    if (!EnvSetup.hasQueryFlag("theatre", "1")) return;
428	    this._hasLoggedFlameAnchorDebug = true;
429	
430	    const flameOptions = this._resolveFlameOptions();
431	    const normalizedIncludes =
432	      this._getNormalizedFlameAnchorIncludes(flameOptions);
433	    const allNodeNames: string[] = [];
434	    const candidateNodeNames: string[] = [];
435	
436	    model.traverse((child) => {
437	      if (child === model) return;
438	      const nodeName = child.name.trim();
439	      if (!nodeName) return;
440	      allNodeNames.push(nodeName);
441	      const normalizedName = nodeName.toLowerCase();
442	      if (!normalizedIncludes.some((value) => normalizedName.includes(value)))
443	        return;
444	      candidateNodeNames.push(nodeName);
445	    });
446	
447	    Logger.info(ROCKET_CLASS, "runObject", "Rocket flame anchor debug.", {
448	      resolvedAnchorName: anchor?.name ?? null,
449	      explicitAnchorName: flameOptions.anchorName?.trim() || null,
450	      anchorNameIncludes: normalizedIncludes,
451	      candidateNodeNames,
452	      allNodeNames,
453	    });
454	  }
455	
456	  private _getNormalizedFlameAnchorIncludes(
457	    options: RocketFlameOptions,
458	  ): string[] {
459	    const includes = options.anchorNameIncludes?.length
460	      ? options.anchorNameIncludes
461	      : [...DEFAULT_FLAME_ANCHOR_NAME_INCLUDES];
462	    return includes.map((value) => value.toLowerCase());
463	  }
464	
465	  private _resolveFlamePosition(
466	    offset: RocketFlameOptions["offset"],
467	  ): THREE.Vector3 {
468	    const x = offset?.x ?? DEFAULT_FLAME_OFFSET.x;
469	    const y = offset?.y ?? DEFAULT_FLAME_OFFSET.y;
470	    const z = offset?.z ?? DEFAULT_FLAME_OFFSET.z;
471	    const anchor = this._flameAnchor;
472	    const model = this._model;
473	    const out = this._flamePositionScratch;
474	    if (!anchor || !model) {
475	      this._modelBounds.getCenter(this._modelBoundsCenter);
476	      out.set(
477	        this._modelBoundsCenter.x + x,
478	        this._modelBounds.min.y + y,
479	        this._modelBoundsCenter.z + z,
480	      );
481	      return out;
482	    }
483	
484	    anchor.getWorldPosition(this._anchorLocalPosition);
485	    model.worldToLocal(this._anchorLocalPosition);
486	    out.set(
487	      this._anchorLocalPosition.x + x,
488	      this._anchorLocalPosition.y + y,
489	      this._anchorLocalPosition.z + z,
490	    );
491	    return out;
492	  }
493	
494	  private _resolveFlameOpacity(options: RocketFlameOptions): number {
495	    return Number.isFinite(options.opacity as number)
496	      ? Number(options.opacity)
497	      : DEFAULT_FLAME_OPACITY;
498	  }
499	
500	  private _resolveFlameRotation(
501	    options: RocketFlameOptions,
502	  ): Required<RocketFlameStateSnapshot>["rotation"] {
503	    const rotation = options.rotation ?? DEFAULT_FLAME_ROTATION;
504	    const out = this._flameRotationScratch;
505	    out.x = Number.isFinite(rotation.x as number)
506	      ? Number(rotation.x)
507	      : DEFAULT_FLAME_ROTATION.x;
508	    out.y = Number.isFinite(rotation.y as number)
509	      ? Number(rotation.y)
510	      : DEFAULT_FLAME_ROTATION.y;
511	    out.z = Number.isFinite(rotation.z as number)
512	      ? Number(rotation.z)
513	      : DEFAULT_FLAME_ROTATION.z;
514	    return out;
515	  }
516	
517	  private _resolveFlameRenderOrder(options: RocketFlameOptions): number {
518	    return Number.isFinite(options.renderOrder as number)
519	      ? Math.round(Number(options.renderOrder))
520	      : DEFAULT_FLAME_RENDER_ORDER;
521	  }
522	
523	  private _resolveFlameSpeed(options: RocketFlameOptions): number {
524	    return Number.isFinite(options.speed as number)
525	      ? Number(options.speed)
526	      : DEFAULT_FLAME_SPEED;
527	  }
528	
529	  private _resolveFlameWave(options: RocketFlameOptions): number {
530	    return Number.isFinite(options.wave as number)
531	      ? Number(options.wave)
532	      : DEFAULT_FLAME_WAVE;
533	  }
534	
535	}
