36	export class AppOrbitRuntime {
37	  private _controls: OrbitControls | null = null;
38	  private _theatreBridge: TheatreBridgePort | null = null;
39	  private _mode: TheatreAuthorMode = "scroll";
40	  private _appliedMode: TheatreAuthorMode | null = null;
