43	  async init(
44	    engine: Engine,
45	    pageConfig: PageConfig,
46	    onAuthorMode: () => void,
47	    onScrollMode: () => void,
48	  ): Promise<void> {
49	    this.dispose();
50	
51	    if (!pageConfig.orbitControls?.enabled) return;
52	    const renderer = engine.getRenderer() as {
53	      domElement?: HTMLCanvasElement;
54	    } | null;
55	    const domElement = renderer?.domElement;
56	    if (!domElement) return;
57	
58	    const controls = new OrbitControls(engine.getCamera(), domElement);
59	    controls.target = engine.getCameraTarget().position;
60	    controls.enableDamping = pageConfig.orbitControls.enableDamping ?? true;
61	    if (typeof pageConfig.orbitControls.dampingFactor === "number") {
62	      controls.dampingFactor = pageConfig.orbitControls.dampingFactor;
63	    }
64	    if (typeof pageConfig.orbitControls.rotateSpeed === "number") {
65	      controls.rotateSpeed = pageConfig.orbitControls.rotateSpeed;
66	    }
67	    if (typeof pageConfig.orbitControls.zoomSpeed === "number") {
68	      controls.zoomSpeed = pageConfig.orbitControls.zoomSpeed;
69	    }
70	    if (typeof pageConfig.orbitControls.panSpeed === "number") {
71	      controls.panSpeed = pageConfig.orbitControls.panSpeed;
72	    }
73	    if (typeof pageConfig.orbitControls.minDistance === "number") {
74	      controls.minDistance = pageConfig.orbitControls.minDistance;
75	    }
76	    if (typeof pageConfig.orbitControls.maxDistance === "number") {
77	      controls.maxDistance = pageConfig.orbitControls.maxDistance;
78	    }
79	    if (typeof pageConfig.orbitControls.minPolarAngle === "number") {
80	      controls.minPolarAngle = pageConfig.orbitControls.minPolarAngle;
81	    }
82	    if (typeof pageConfig.orbitControls.maxPolarAngle === "number") {
83	      controls.maxPolarAngle = pageConfig.orbitControls.maxPolarAngle;
84	    }
85	    controls.update();
86	    this._controls = controls;
87	
88	    const pageType = pageConfig.pageId;
89	    if (!THEATRE_BRIDGE_FACTORIES[pageType]) return;
90	
91	    const theatreBridge = await this._createTheatreBridge(
92	      pageType,
93	      engine,
94	      controls,
95	      {
96	        onModeChange: (mode) => {
97	          this._mode = mode;
98	          this._syncMode(onAuthorMode, onScrollMode);
99	        },
100	        onPlaybackChange: () => {
101	          this._syncMode(onAuthorMode, onScrollMode);
102	        },
103	      },
104	    );
105	    this._theatreBridge = theatreBridge;
106	    this._mode = theatreBridge ? "author" : "scroll";
107	    this._syncMode(onAuthorMode, onScrollMode);
108	  }
109	
110	  update(): void {
111	    if (!this._controls) return;
112	    if (this._paused) return;
113	    if (this._mode === "author" && this._theatreBridge) return;
114	    this._controls.update();
115	  }
116	
117	  pause(): void {
118	    this._paused = true;
119	  }
120	
121	  resume(engine: Engine): void {
122	    const controls = this._controls;
123	    if (!controls) return;
124	    this._paused = false;
125	    controls.target.copy(engine.getCameraTarget().position);
126	    controls.update();
127	  }
128	
129	  dispose(): void {
130	    this._theatreBridge?.dispose();
131	    this._theatreBridge = null;
132	    this._controls?.dispose();
133	    this._controls = null;
134	    this._mode = "scroll";
135	    this._appliedMode = null;
136	    this._paused = false;
137	  }
138	
139	  private _syncMode(onAuthorMode: () => void, onScrollMode: () => void): void {
140	    const controls = this._controls;
141	    if (!controls) return;
142	
143	    if (this._mode !== this._appliedMode) {
144	      if (this._mode === "author") onAuthorMode();
145	      else onScrollMode();
146	      this._appliedMode = this._mode;
147	    }
148	
149	    controls.enabled = this._mode === "author";
150	  }
151	
152	  private async _createTheatreBridge(
153	    pageType: string,
154	    engine: Engine,
155	    controls: OrbitControls,
156	    hooks: TheatreAuthorBridgeHooks,
157	  ): Promise<TheatreBridgePort | null> {
158	    if (
159	      !EnvSetup.hasQueryFlag(THEATRE_QUERY_KEY, THEATRE_QUERY_ENABLED)
160	    ) {
161	      return null;
162	    }
163	    const factory = THEATRE_BRIDGE_FACTORIES[pageType];
164	    if (!factory) return null;
165	    return factory(engine, controls, hooks);
166	  }
167	}
