3	import { FrameScheduler } from "../utils/FrameScheduler.js";
4	export { type AnimationLoopOptions } from "../types/runtime.types.js";
5	
6	export const MAX_DELTA_SECONDS = 0.1;
7	
8	const BUDGET_MS = 33;
9	
10	export class AnimationLoop {
11	  private _onUpdate: (deltaTime: number) => void;
12	  private _onRender: () => void;
13	  private _clock: THREE.Clock;
14	  private _id: number | null = null;
15	  private _running = false;
16	  private _frameStart = 0;
17	  private _frameExceeded = false;
18	  private _budgetMs = BUDGET_MS;
19	  private _visibilityListenerAttached = false;
20	  private _pageshowListenerAttached = false;
21	  private _resumeOnVisible = false;
22	  private readonly _visibilityHandler = (): void => {
23	    if (typeof document === "undefined") return;
24	    if (document.hidden) {
25	      if (!this._running) return;
26	      this._resumeOnVisible = true;
27	      this.stop();
28	      return;
29	    }
30	    if (!this._resumeOnVisible) return;
31	    this._resumeOnVisible = false;
32	    this.start();
33	  };
34	  private readonly _pageshowHandler = (e: PageTransitionEvent): void => {
35	    if (!e.persisted) return;
36	    // bfcache 복원: JS가 freeze됐다 풀리면서 RAF 체인이 끊김 → 강제 재시작
37	    this._running = false;
38	    if (this._id !== null) {
39	      FrameScheduler.cancel(this._id);
40	      this._id = null;
41	    }
42	    this._resumeOnVisible = false;
43	    this.start();
44	  };
45	
46	  get frameExceeded(): boolean {
47	    return this._frameExceeded;
48	  }
49	
50	  private _loop = (): void => {
51	    if (!this._running) return;
52	    this._id = FrameScheduler.request(this._loop);
53	    if (this._frameStart > 0) {
54	      this._frameExceeded =
55	        performance.now() - this._frameStart > this._budgetMs;
56	    }
57	    this._frameStart = performance.now();
58	    const delta = Math.min(this._clock.getDelta(), MAX_DELTA_SECONDS);
59	    this._onUpdate(delta);
60	    this._onRender();
61	  };
62	
63	  constructor(opts: AnimationLoopOptions = {}) {
64	    this._onUpdate = opts.onUpdate ?? (() => {});
65	    this._onRender = opts.onRender ?? (() => {});
66	    if (
67	      Number.isFinite(opts.budgetMs as number) &&
68	      (opts.budgetMs as number) > 0
69	    ) {
70	      this._budgetMs = opts.budgetMs as number;
71	    }
72	    this._clock = new THREE.Clock();
73	  }
74	
75	  start(): void {
76	    if (this._running) return;
77	    if (typeof document !== "undefined" && !this._visibilityListenerAttached) {
78	      document.addEventListener("visibilitychange", this._visibilityHandler);
79	      this._visibilityListenerAttached = true;
80	    }
81	    if (typeof window !== "undefined" && !this._pageshowListenerAttached) {
82	      window.addEventListener("pageshow", this._pageshowHandler);
83	      this._pageshowListenerAttached = true;
84	    }
85	    this._running = true;
86	    this._clock.start();
87	    this._loop();
88	  }
89	
90	  stop(): void {
91	    if (!this._running) return;
92	    this._running = false;
93	    if (this._id != null) {
94	      FrameScheduler.cancel(this._id);
95	      this._id = null;
96	    }
97	    this._clock?.stop();
98	  }
99	
100	  dispose(): void {
101	    this.stop();
102	    if (typeof document !== "undefined" && this._visibilityListenerAttached) {
103	      document.removeEventListener("visibilitychange", this._visibilityHandler);
104	      this._visibilityListenerAttached = false;
105	    }
106	    if (typeof window !== "undefined" && this._pageshowListenerAttached) {
107	      window.removeEventListener("pageshow", this._pageshowHandler);
108	      this._pageshowListenerAttached = false;
109	    }
110	    this._resumeOnVisible = false;
111	  }
112	}
